        return added;
      };
      const sent = await wait(limits.send, async () => {
        const fresh = await readAfterClick();
        if (!fresh) return null;
        const added = tail(fresh);
        return fresh.route && added[0] ? {fresh, user:added[0]} : null;
      });
      await saveStep({...getStep(), state:'sent', user:{...sent.user, url:sent.fresh.url,
        route:sent.fresh.route, documentId:sent.fresh.documentId, observedAt:now()}});
      await saveStep({...getStep(), state:'waiting_reply'});
      let signature = null;
      const completed = await wait(limits.reply, async () => {
        const fresh = await readAfterClick();
        if (!fresh) {signature = null; return null;}
        const added = tail(fresh);
        requireState(fresh.route === sent.fresh.route && added[0]?.key === sent.user.key,
          'E_RELAY_TURN', '已确认的对话或用户轮次变化');
        const replies = added.slice(1);
        requireState(replies.length <= 1 && replies.every(m => m.role === 'assistant'),
          'E_RELAY_TURN', '助手回复轮次不唯一');
        const reply = replies[0];
        if (!reply?.complete || reply.streaming || fresh.busy) {signature = null; return null;}
        const current = JSON.stringify([fresh.route, reply.key, reply.text]);
        const stable = current === signature;
        signature = current;
        return stable ? {reply, fresh} : null; // Explicit completion AND a stable second observation.
      });
      return {raw:completed.reply.text,
        conversation:completed.fresh.route, url:completed.fresh.url,
        documentId:completed.fresh.documentId, userMessageId:sent.user.key,
        assistantMessageId:completed.reply.key, completionSignal:'official-turn-complete-or-copy-action; no-streaming; stable-twice',
        completedAt:now()};
    }
  };
}

import {createChatGPTControllerSite} from './site.js';
import {runCalculationRelay} from './relay.js';

// Public Controller lexical capabilities; no website MAIN or private Host RPC.
export default async function main() {
  return runCalculationRelay({site:createChatGPTControllerSite(page), store:AppStorage, params});
}

import {createConversationSession, assertBlank} from './conversation.js';
import {validateParams, calculationInput, sameInput, makePrompt, parseReply, validateJournal, validateRelayResult} from './contract.js';

const PREFIX = 'opendesk.chatgpt-calculation-relay.v1:';
export const ACTIVE_KEY = PREFIX + 'active';
export const journalKey = runId => PREFIX + runId;
const fail = (code, message) => Object.assign(new Error(code + ': ' + message), {code});
const requireState = (ok, code, message) => {if (!ok) throw fail(code, message);};
const parseRecord = raw => {
  if (raw === null || raw === undefined) return null;
  try {
    const value = JSON.parse(raw);
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid record');
    return value;
  } catch {throw fail('E_RELAY_STORAGE', '存储内容无法解析，保留原记录');}
};
const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export {makePrompt, parseReply} from './contract.js';

// One fixed A→B business flow, not a scheduler or a replacement RunHost.
// store is the public AppStorage facade. Tests exercise this same module with
// isolated dependencies; those tests never assert real Chrome execution.
export async function runCalculationRelay({site, store, params = {},
  now = () => Date.now(), sleep = ms => new Promise(resolve => setTimeout(resolve, ms)),
  newId = () => 'relay-' + crypto.randomUUID(), limits = {ready:8000, send:6000, reply:40000, poll:500}}) {
  // The reviewed Task has a 120s deadline. Business work uses a shared 105s
  // budget with its final 5s reserved for persistence; never extend the Host deadline.
  const workDeadline = now() + (limits.total ?? 105000) - (limits.settle ?? 5000);
  const assertBudget = () => requireState(now() < workDeadline, 'E_RELAY_TIMEOUT', '接力总预算不足，停止新副作用并落账');
  validateParams(params);
  const input = calculationInput(params), {addend, secondAddend, multiplier} = input;
  const operation = params.operation ?? 'run';
  const active = parseRecord(await store.getItem(ACTIVE_KEY));
  if (active) requireState(typeof active.runId === 'string' && active.key === journalKey(active.runId),
    'E_RELAY_STORAGE', '当前接力指针无效');
  const runId = params.runId ?? (operation === 'status' ? active?.runId : newId());
  if (!runId) return {status:'not_found'};
  requireState(/^[a-zA-Z0-9_-]{8,80}$/.test(runId), 'E_RELAY_PARAMS', '运行标识无效');
  const key = journalKey(runId);
  const read = async () => {
    const record = parseRecord(await store.getItem(key));
    if (record !== null) validateJournal(record, runId);
    return record;
  };
  let state = await read();
  if (operation === 'status') return state ? {...state, journalKey:key, readOnly:true,
    statusSource:'persistent-journal', needsReconciliation:state.status !== 'completed'} : {status:'not_found', runId};
  if (operation === 'inspect') {
    const bound = await site.bind(), step = state?.steps[state.error?.step];
    requireState(!step || bound === step.documentId, 'E_RELAY_TARGET', '只读对账必须绑定原文档');
    return {runId, readOnly:true, record:state,
      observation:await site.read(step?.baseline), selectorDiagnostics:await site.inspect(runId)};
  }
  const reconciling = operation === 'reconcile';
  if (reconciling) requireState(params.runId && state?.status === 'unknown' && sameInput(input, state) &&
    active?.runId === runId && ['A','B'].includes(state.error?.step) &&
    state.steps[state.error.step].clickIntent === true,
    'E_RELAY_RECONCILE', '只能显式对账同一 runId 已有点击意图的未知步骤；禁止重发');
  if (state) {
    requireState(sameInput(input, state), 'E_RELAY_PARAMS', '同一 runId 不能更换测试输入');
    if (!reconciling) return {...state, journalKey:key, readOnly:true,
    statusSource:'persistent-journal', needsReconciliation:state.status !== 'completed'}; // A repeated Run is NOT a resend.
  }
  if (active && !reconciling) {
    const old = parseRecord(await store.getItem(active.key));
    requireState(old?.runId === active.runId && old.status === 'completed',
      'E_RELAY_PENDING', '前一接力未核清；仅允许 status 读取，禁止新发送');
    validateJournal(old, active.runId);
  }
  const assertOwner = async () => requireState((await store.getItem(ACTIVE_KEY)) === JSON.stringify({runId, key}),
    'E_RELAY_OWNER', '接力指针改变，停止发送');
  const write = async record => {
    await assertOwner();
    const raw = JSON.stringify({...record, updatedAt:now()});
    await store.setItem(key, raw);
    requireState(await store.getItem(key) === raw, 'E_RELAY_READBACK', '持久化读回不一致，停止接力');
    return JSON.parse(raw);
  };
  const wait = async (timeout, check) => {
    const deadline = Math.min(now() + timeout, workDeadline);
    for (;;) {
      assertBudget();
      const value = await check();
      if (value) return value;
      requireState(now() < deadline, 'E_RELAY_TIMEOUT', '等待期限已到；禁止补发');
      await sleep(limits.poll);
    }
  };
  const conversation = createConversationSession({site, wait, assertOwner, assertBudget, now, limits});
  const firstDocument = await conversation.bind();
  const initial = await site.read();
  let currentStep = reconciling ? state.error.step : 'A';
  if (reconciling) {
    requireState(firstDocument === state.steps[currentStep].documentId && initial.draft === '' && !initial.rich,
      'E_RELAY_RECONCILE', '对账必须回到原受控文档且无草稿/附件；未发送任何消息');
    await assertOwner();
  } else {
    assertBlank(initial); // Fail BEFORE claiming storage or changing an existing draft.
    await store.setItem(ACTIVE_KEY, JSON.stringify({runId, key}));
    await assertOwner();
    state = await write({format:'opendesk.chatgpt-calculation-relay.v1', runId, addend, secondAddend, multiplier,
      status:'queued', createdAt:now(), steps:{A:{state:'queued'}, B:{state:'queued'}}});
  }
  async function execute(stepId, snapshot, operand, expected, reconcile = false) {
    const observed = await conversation.exchange({snapshot, prompt:makePrompt(runId, stepId, operand, input),
      nonce:runId + '-' + stepId, reconcile, getStep:() => state.steps[stepId],
      saveStep:async step => {
        state.status = 'running';
        state.steps[stepId] = step;
        state = await write(state);
      }});
    const result = parseReply(observed.raw, runId, stepId, expected);
    state.steps[stepId].state = 'completed';
    state.steps[stepId].result = {...result, ...observed};
    state = await write(state);
    return (await read()).steps[stepId].result; // Actual trusted store read; not an in-memory handoff.
  }
  try {
    if (currentStep === 'A') await execute('A', initial, addend, addend + secondAddend, reconciling);
    const savedA = (await read()).steps.A;
    requireState(savedA.state === 'completed' && savedA.result?.value === addend + secondAddend,
      'E_RELAY_READBACK', 'A 未有效完成并持久化');
    let next = initial;
    if (currentStep === 'A') {
      state.handoff = {state:'navigating', fromDocumentId:firstDocument,
        fromConversation:savedA.result.conversation, sourceJournalKey:key, sourceStep:'A'};
      state = await write(state); // Persist BEFORE navigation; never use Page-world memory for B.
      currentStep = 'B';
      await assertOwner();
      assertBudget();
      const nextDocument = await conversation.newConversation(Math.min(20000, workDeadline - now()));
      requireState(nextDocument && nextDocument !== firstDocument, 'E_RELAY_DOCUMENT', '新文档未可信重新绑定');
      next = await wait(limits.ready, async () => {
        try {return await site.read();}
        catch (error) {if (String(error.message).startsWith('E_RELAY_SITE:')) return null; throw error;}
      });
      assertBlank(next);
      requireState(next.documentId === nextDocument && next.route === null && next.messages.length === 0,
        'E_RELAY_CONVERSATION', '导航后不是全新空对话');
      const readAfterNavigation = await read();
      requireState(readAfterNavigation?.steps.A.state === 'completed' &&
        equal(readAfterNavigation.steps.A.result, savedA.result), 'E_RELAY_READBACK', '导航后无法读回相同 A 结果');
      state = readAfterNavigation;
      state.handoff = {...state.handoff, state:'bound', toDocumentId:nextDocument};
      state = await write(state);
    } else {
      requireState(state.handoff?.state === 'bound' && state.handoff.toDocumentId === firstDocument,
        'E_RELAY_RECONCILE', 'B 缺少原导航交接身份');
    }
    await execute('B', next, savedA.result.value, savedA.result.value * multiplier,
      reconciling && state.error?.step === 'B');
    requireState(state.steps.B.result.conversation !== state.steps.A.result.conversation,
      'E_RELAY_CONVERSATION', 'A 与 B 不是不同对话');
    state.status = 'completed';
    delete state.error;
    state = await write(state);
    return validateRelayResult({...await read(), journalKey:key}, runId); // Business evidence, not a Host receipt.
  } catch (error) {
    state.status = 'unknown';
    state.steps[currentStep].state = 'unknown';
    state.error = {code:error.code || 'E_RELAY_OPERATION', message:String(error.message).slice(0,600), step:currentStep};
    try {state = await write(state);} catch { /* Prior sending/navigating write remains the fence. */ }
    throw fail('E_RELAY_UNKNOWN', `${state.error.message}；runId=${runId}；只读 status 对账，禁止自动重发`);
  }
}

// Site-specific DOM adapter over the existing, authorized Controller Page API.
// Composer/confirmation guards follow chatgpt-send-queue/src/site.js (read-only
// reference). Its Page-only factory cannot be imported by an independent project.
// This function is serialized by page.evaluate: keep every dependency inside it.
export function chatgptDOM(action, input = {}) {
  const doc = document, win = window;
  const fail = reason => ({ok:false, reason});
  const routeMatch = win.location.pathname.match(/^(?:\/g\/[^/]+)?\/c\/([a-z0-9-]{8,})\/?$/i);
  const route = routeMatch ? 'c/' + routeMatch[1].toLowerCase() : null;
  if (win !== win.top || win.location.origin !== 'https://chatgpt.com' ||
      (!route && win.location.pathname !== '/') ||
      new URL(win.location.href).searchParams.get('temporary-chat') === 'true')
    return fail('仅支持官方 ChatGPT 顶层持久对话或新对话首页');
  const visible = el => el.isConnected && !el.closest('[hidden],[inert],[aria-hidden="true"],[data-opendesk-ui-owner]') &&
    win.getComputedStyle(el).display !== 'none' && win.getComputedStyle(el).visibility !== 'hidden' && el.getClientRects().length > 0;
  const editors = [...doc.querySelectorAll('#prompt-textarea,[data-testid="composer-input"],form textarea[data-testid],form [contenteditable="true"][role="textbox"][data-composer-markdown]')]
    .filter(el => visible(el) && (el.isContentEditable || typeof el.value === 'string'));
  if (editors.length !== 1) return fail('原生编辑器不存在或不唯一');
  const editor = editors[0], form = editor.closest('form');
  if (!form || !form.isConnected) return fail('无法确认原生表单');
  if (action === 'inspect') {
    const walker = doc.createTreeWalker(doc.body, 4), matches = [];
    for (let node; (node = walker.nextNode()) && matches.length < 3;) {
      if (!node.textContent.includes(input.runId)) continue;
      const ancestors = [];
      for (let el = node.parentElement, i = 0; el && i < 14; el = el.parentElement, i++)
        ancestors.push({tag:el.tagName, attributes:Object.fromEntries([...el.attributes].map(a => [a.name,a.value])),
          actions:i >= 7 ? [...el.querySelectorAll('button')].slice(0,8).map(b => ({testId:b.getAttribute('data-testid'), label:b.getAttribute('aria-label')})) : undefined});
      matches.push({text:node.textContent.slice(0,600), ancestors});
    }
    return {ok:true, route, url:win.location.href, matches, bodyHasRun:doc.body.textContent.includes(input.runId)};
  }
  const readDraft = () => {
    if (typeof editor.value === 'string') return editor.value;
    const paragraph = editor.firstElementChild, br = paragraph?.firstElementChild;
    // The official empty placeholder renders innerText="\n" after Delete.
    // Normalize only its observed empty structure, never trim a user's draft.
    if (editor.childNodes.length === 1 && paragraph?.tagName === 'P' &&
        paragraph.getAttribute('data-empty-paragraph') === 'true' && paragraph.textContent === '' &&
        paragraph.childNodes.length === 1 && br?.tagName === 'BR' &&
        br.classList.contains('ProseMirror-trailingBreak')) return '';
    return editor.innerText ?? editor.textContent ?? '';
  };
  const draft = readDraft();
  const rich = !!form.querySelector('[data-attachment-id],[data-file-id]') ||
    !!editor.querySelector('img,video,canvas,iframe,[data-attachment-id],[data-file-id]');
  const buttons = [...form.querySelectorAll('button')].filter(visible);
  const stops = buttons.filter(el => /^(stop-button|composer-stop-button)$/.test(el.getAttribute('data-testid') || '') ||
    /^(stop generating|stop generation|stop responding|stop|停止生成|停止回复|停止)$/i.test(el.getAttribute('aria-label') || ''));
  const sends = buttons.filter(el => /^(send-button|composer-send-button|composer-submit-button)$/.test(el.getAttribute('data-testid') || '') ||
    /^(send message|send prompt|send|发送消息|发送|送出)$/i.test(el.getAttribute('aria-label') || ''));
  if (stops.length > 1 || sends.length > 1) return fail('发送或停止按钮存在歧义');
  const selector = '[data-message-author-role="user"],[data-message-author-role="assistant"],[data-message-role="user"],[data-message-role="assistant"],[data-chatgpt-search-unit-key][data-chatgpt-search-message-ids]';
  const nodes = [...doc.querySelectorAll(selector)].filter(el => !el.parentElement?.closest(selector));
  if (nodes.length > 160) return fail('测试对话历史过长，请使用专用短对话');
  const baseline = new Set(input.baseline || []);
  const messages = nodes.map(el => {
    const unit = el.getAttribute('data-chatgpt-search-unit-key');
    const unitRole = unit?.match(/:(user|assistant)$/)?.[1];
    const role = el.getAttribute('data-message-author-role') || el.getAttribute('data-message-role') || unitRole;
    const turn = el.closest('article,[data-testid^="conversation-turn-"],[data-turn-id],[data-turn-key]') || el;
    // Current official UI repeats the assistant ID in this attribute. Accept
    // that one identity, but never turn multiple distinct IDs into one message.
    const unitIds = [...new Set((el.getAttribute('data-chatgpt-search-message-ids') || '').split(/\s+/).filter(Boolean))];
    const unitValid = unitRole && unitIds.length === 1 && !!el.querySelector(unitRole === 'user' ?
      '[data-user-message-bubble="true"]' : '[data-markdown-text-style="assistant-message"]');
    const id = unit ? (unitValid ? unitIds[0] : null) :
      el.getAttribute('data-message-id') || el.id || turn.getAttribute('data-turn-id') || turn.getAttribute('data-testid') || turn.id;
    const key = id ? role + ':' + id : null;
    const stateNode = el.closest('[data-talvt-turn-state]') || turn;
    const turnState = stateNode.getAttribute('data-talvt-turn-state');
    const streaming = (turnState && turnState !== 'complete') ||
      el.matches('[data-is-streaming="true"],[aria-busy="true"],.result-streaming') ||
      !!turn.querySelector('[data-is-streaming="true"],[aria-busy="true"],.result-streaming');
    const complete = role === 'assistant' && !streaming &&
      (turnState === 'complete' || !!turn.querySelector('[data-testid="copy-turn-action-button"],[data-assistant-message-actions]'));
    // History contributes identity only; read text solely for this new turn.
    const content = el.querySelector('[data-testid="message-content"],[data-message-content],.whitespace-pre-wrap,.markdown,[data-markdown-text-style="assistant-message"]') || el;
    return {key, role, complete, streaming:!!streaming,
      text:input.baseline && !baseline.has(key) ? (content.innerText ?? content.textContent ?? '') : null};
  });
  const keys = messages.map(m => m.key);
  if (keys.some(key => !key) || new Set(keys).size !== keys.length) return fail('网页消息缺少唯一轮次身份');
  const last = messages.at(-1);
  const idle = !stops.length && (!last || last.role === 'assistant' && last.complete);
  const sendReady = sends.length === 1 && !sends[0].disabled && sends[0].getAttribute('aria-disabled') !== 'true';
  const snapshot = {ok:true, url:win.location.href, route, draft, rich, idle, busy:!!stops.length,
    sendReady, messages};
  if (action === 'read') return snapshot;
  const equalKeys = expected => JSON.stringify(keys) === JSON.stringify(expected);
  const tokenKey = Symbol.for('opendesk.chatgpt-calculation-relay.prepared.v1');
  if (action === 'fill') {
    if (route !== input.route || !equalKeys(input.keys) || !idle || rich || draft !== '' ||
        editor.readOnly || editor.getAttribute('aria-disabled') === 'true') return fail('草稿、回复状态或目标已变化，未填入');
    if (typeof editor.value === 'string') {
      const proto = editor.tagName === 'TEXTAREA' ? win.HTMLTextAreaElement.prototype : win.HTMLInputElement.prototype;
      Object.getOwnPropertyDescriptor(proto, 'value').set.call(editor, input.text);
      editor.dispatchEvent(new win.InputEvent('input', {bubbles:true, inputType:'insertText', data:input.text}));
    } else {
      editor.focus();
      const selection = win.getSelection(), range = doc.createRange();
      range.selectNodeContents(editor); selection.removeAllRanges(); selection.addRange(range);
      if (!doc.execCommand('insertText', false, input.text)) return fail('官网未接收输入，未点击发送');
    }
    const actual = readDraft();
    if (!editor.isConnected || actual !== input.text) return fail('输入读回不一致，未点击发送');
    // A replaced React editor/form cannot inherit the right to click.
    editor[tokenKey] = {nonce:input.nonce, form, text:input.text, route, keys:input.keys};
    return {ok:true};
  }
  if (action === 'send') {
    const token = editor[tokenKey];
    if (!token || token.nonce !== input.nonce || token.form !== form || token.text !== input.text ||
        token.route !== route || !equalKeys(token.keys) || rich || !idle || !sendReady || draft !== input.text)
      return fail('准备令牌、编辑器或消息状态已变化，未点击发送');
    delete editor[tokenKey]; // Consume BEFORE the only click, including throwing clicks.
    sends[0].click();
    return {ok:true, clicked:true}; // Not a send receipt; the Controller must read the new user turn.
  }
  return fail('未知站点动作');
}

export function createChatGPTControllerSite(page) {
  let documentId = null;
  return {
    async bind() {
      const {document:target} = await page.observe({root:'body', maxDepth:1, maxNodes:1, maxChars:256});
      if (!target?.documentId || new URL(target.url).origin !== 'https://chatgpt.com')
        throw new Error('E_RELAY_TARGET: 缺少可信 ChatGPT documentId');
      documentId = target.documentId;
      return documentId;
    },
    async read(baseline) {
      const snapshot = await page.evaluate(chatgptDOM, 'read', {baseline});
      if (!snapshot.ok) throw new Error('E_RELAY_SITE: ' + snapshot.reason);
      return {...snapshot, documentId};
    },
    async inspect(runId) {return page.evaluate(chatgptDOM, 'inspect', {runId});},
    async fill(step) {
      const receipt = await page.evaluate(chatgptDOM, 'fill', {
        route:step.startRoute, keys:step.baseline, text:step.prompt, nonce:step.nonce});
      if (!receipt.ok) throw new Error('E_RELAY_FILL: ' + receipt.reason);
    },
    async send(step) {
      const receipt = await page.evaluate(chatgptDOM, 'send', {text:step.prompt, nonce:step.nonce});
      if (!receipt.ok || !receipt.clicked) throw new Error('E_RELAY_SEND: ' + receipt.reason);
    },
    async newConversation(timeout = 20000) {
      await page.goto('https://chatgpt.com/', {timeout, waitUntil:'domcontentloaded'});
      return this.bind(); // Use the existing Host navigation handoff, never carry A's document.
    }
  };
}
